factorial:
#include <bits/stdc++.h>
using namespace std;
using ll = long long;

ll factorial(int n) {
    if (n == 0) return 1;
    ll x = factorial(n - 1);
    return n * x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cout << factorial(n) << '\n';
}

hanoi:
#include <bits/stdc++.h>
using namespace std;

int moves(int n) {
    if (n == 0) return 0;
    return 2 * moves(n - 1) + 1;
}

void hanoi(int n, int from, int to, int aux) {
    if (n == 0) return;
    hanoi(n - 1, from, aux, to);
    cout << from << ' ' << to << '\n';
    hanoi(n - 1, aux, to, from);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cout << moves(n) << '\n';
    hanoi(n, 1, 3, 2);
}

parentheses:
#include <bits/stdc++.h>
using namespace std;

void generate(int open, int close, int n, string &cur) {
    if (open == n && close == n) {
        cout << cur << '\n';
        return;
    }
    if (open < n) {
        cur.push_back('(');
        generate(open + 1, close, n, cur);
        cur.pop_back();
    }
    if (close < open) {
        cur.push_back(')');
        generate(open, close + 1, n, cur);
        cur.pop_back();
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string cur;
    cur.reserve(2 * n);
    generate(0, 0, n, cur);
}
